"""Structured mutant generation over the h2 accept parents (offline, no RPC).

Parses the fork's tx prefix (FCMP++/Carrot wire format as shipped in the
fork: vin = type varint, amount varint, key_offsets count + varints,
THEN k_image 32B; carrot_v1 outputs = key 32B + view_tag 3B + janus anchor
16B), verifies parse->serialize reproduces each parent byte-for-byte
(calibration), then emits structured ENC and VIN mutants.

Calibration rule: parse(tx) -> serialize(tx) must reproduce the input bytes
EXACTLY; parents that fail round-trip or have vin_count < 1 are skipped.

Output: corpus-parm-mut/<cid>.hex (cid = encmutNNNNN / vinmutNNNNN) and
labels.json with {id, parent, parent_height, mutation, label, class, sha256}.
label stays null — these cases are LABELED LIVE by the fork/stock oracle
comparison (fork_compare.py parm-mut), no recorded third party exists.

Usage: python3 -I mutant_gen.py --parents PARENTS.jsonl --outdir OUTDIR"""
import argparse
import hashlib
import json
import os

_ap = argparse.ArgumentParser(
    description="Structured mutants from accepted corpus parents "
                "(no defaults; paths are explicit arguments)")
_ap.add_argument("--parents", required=True, metavar="PATH",
                 help="accept-parents JSONL from the corpus capture "
                      "(required, no default)")
_ap.add_argument("--outdir", required=True, metavar="PATH",
                 help="output directory for mutants and labels.json "
                      "(required, no default)")
_args = _ap.parse_args()
PARENTS = _args.parents
OUTDIR = _args.outdir
PER_OP = 50          # ~50 cases per op; total ~400 across the 8 ops

# tx_out target types present in this fork's corpus -> target byte length
# (1 = txout_to_carrot_v1: key 32 + view_tag 3 + encrypted janus anchor 16;
#  2 = txout_to_key: key 32; 3 = txout_to_tagged_key: key 32 + view tag 1)
TARGET_LEN = {1: 51, 2: 32, 3: 33}


def read_varint(b, i):
    v = 0
    s = 0
    while True:
        if i >= len(b):
            raise ValueError("varint past end")
        c = b[i]
        i += 1
        v |= (c & 0x7f) << s
        s += 7
        if s > 63:
            raise ValueError("varint too long")
        if not c & 0x80:
            return v, i


def write_varint(v):
    out = bytearray()
    while True:
        b = v & 0x7f
        v >>= 7
        if v:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def overlong_varint(v):
    """VALUE-PRESERVING non-canonical encoding: same value in one group more
    than needed, e.g. version 2 -> 0x82 0x00 (decodes back to 2)."""
    out = bytearray([(v & 0x7f) | 0x80])
    v >>= 7
    while True:
        b = v & 0x7f
        v >>= 7
        if v:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def parse_prefix(b):
    """Parse the tx prefix; the rct signature blob is kept as an opaque tail."""
    i = 0
    version, i = read_varint(b, i)
    unlock_time, i = read_varint(b, i)
    vin_count, i = read_varint(b, i)
    vins = []
    for _ in range(vin_count):
        t, i = read_varint(b, i)
        if t != 2:
            raise ValueError("vin type %d at %d" % (t, i))
        amount, i = read_varint(b, i)
        oc, i = read_varint(b, i)
        offsets = []
        for _ in range(oc):
            o, i = read_varint(b, i)
            offsets.append(o)
        ki = b[i:i + 32]
        if len(ki) != 32:
            raise ValueError("k_image short at %d" % i)
        i += 32
        vins.append({"amount": amount, "offsets": offsets, "ki": ki})
    vout_count, i = read_varint(b, i)
    vouts = []
    for _ in range(vout_count):
        amount, i = read_varint(b, i)
        t, i = read_varint(b, i)
        n = TARGET_LEN.get(t)
        if n is None:
            raise ValueError("vout type %d at %d" % (t, i))
        tgt = b[i:i + n]
        if len(tgt) != n:
            raise ValueError("target short at %d" % i)
        i += n
        vouts.append({"amount": amount, "type": t, "target": tgt})
    es, i = read_varint(b, i)
    extra = b[i:i + es]
    if len(extra) != es:
        raise ValueError("extra short at %d" % i)
    i += es
    return {"version": version, "unlock_time": unlock_time, "vins": vins,
            "vouts": vouts, "extra": extra, "tail": b[i:]}


def serialize_prefix(tx):
    o = write_varint(tx["version"]) + write_varint(tx["unlock_time"]) \
        + write_varint(len(tx["vins"]))
    for vin in tx["vins"]:
        o += write_varint(2) + write_varint(vin["amount"]) \
            + write_varint(len(vin["offsets"]))
        for x in vin["offsets"]:
            o += write_varint(x)
        o += vin["ki"]
    o += write_varint(len(tx["vouts"]))
    for vout in tx["vouts"]:
        o += write_varint(vout["amount"]) + write_varint(vout["type"]) \
            + vout["target"]
    o += write_varint(len(tx["extra"])) + tx["extra"] + tx["tail"]
    return bytes(o)


# --- mutation ops (name -> function(tx) -> mutated tx) -------------------

def enc_overlong_version(tx):
    # re-encode the version varint overlong in the raw blob
    return None  # handled specially below (raw-header rewrite)


def enc_overlong_vincount(tx):
    return None  # raw-header rewrite


def enc_trailing_junk(tx):
    return None  # whole-blob op


def enc_leading_junk(tx):
    return None  # whole-blob op


def vin_dup(tx):
    t = dict(tx)
    t["vins"] = list(tx["vins"]) + [dict(tx["vins"][0])]
    return t


def vin_ki_copy(tx):
    t = dict(tx)
    vins = [dict(v) for v in tx["vins"]]
    vins[0]["ki"] = vins[1]["ki"]
    t["vins"] = vins
    return t


def vin_ki_swap(tx):
    t = dict(tx)
    vins = [dict(v) for v in tx["vins"]]
    vins[0]["ki"], vins[1]["ki"] = vins[1]["ki"], vins[0]["ki"]
    t["vins"] = vins
    return t


def vin_amount_bump(tx):
    t = dict(tx)
    vins = [dict(v) for v in tx["vins"]]
    vins[0]["amount"] = vins[0]["amount"] + 1  # per-input claim tamper
    t["vins"] = vins
    return t


def apply_op(op, tx, blob):
    """Returns the mutated blob ( ENC header/junk ops work on the raw wire
    bytes; VIN ops mutate the parsed prefix and re-serialize)."""
    if op == "enc_overlong_version":
        return overlong_varint(tx["version"]) + blob[1:]
    if op == "enc_overlong_vincount":
        vlen = len(write_varint(tx["version"])) + len(write_varint(tx["unlock_time"]))
        return blob[:vlen] + overlong_varint(len(tx["vins"])) + blob[vlen + len(write_varint(len(tx["vins"]))):]
    if op == "enc_trailing_junk":
        return blob + b"\x00\x00"
    if op == "enc_leading_junk":
        return b"\x00" + blob
    return serialize_prefix(VIN_OPS[op](tx))


VIN_OPS = {"vin_dup": vin_dup, "vin_ki_copy": vin_ki_copy,
           "vin_ki_swap": vin_ki_swap, "vin_amount_bump": vin_amount_bump}
ENC_OPS = ["enc_overlong_version", "enc_overlong_vincount",
           "enc_trailing_junk", "enc_leading_junk"]
ALL_OPS = ENC_OPS + list(VIN_OPS)


def main():
    parsed = []
    skipped_rt = 0
    skipped_vc = 0
    for line in open(PARENTS):
        rec = json.loads(line)
        b = bytes.fromhex(rec["as_hex"])
        try:
            tx = parse_prefix(b)
            if serialize_prefix(tx) != b:
                raise ValueError("round-trip mismatch")
        except (ValueError, IndexError) as e:
            skipped_rt += 1
            print("skip %s: %s" % (rec.get("tx_hash", "?")[:12], e))
            continue
        if len(tx["vins"]) < 1:
            skipped_vc += 1
            continue
        parsed.append((rec, tx))

    multi = [r for r in parsed if len(r[1]["vins"]) >= 2]
    print("parents parsed+roundtrip OK: %d  (skipped roundtrip: %d, "
          "vin_count<1: %d)" % (len(parsed), skipped_rt, skipped_vc))
    print("multi-input parents (vin_count>=2): %d" % len(multi))

    os.makedirs(OUTDIR, exist_ok=True)
    cases = []
    counters = {"enc": 0, "vin": 0}
    for op in ALL_OPS:
        pool = multi if op in VIN_OPS else parsed
        made = 0
        seen = set()
        k = 0
        while made < PER_OP and k < len(pool) * 3:
            rec, tx = pool[k % len(pool)]
            k += 1
            if rec["tx_hash"] in seen:
                continue  # one op per parent within an op
            seen.add(rec["tx_hash"])
            try:
                blob = apply_op(op, tx, bytes.fromhex(rec["as_hex"]))
            except ValueError as e:
                continue  # parent not eligible for this op (e.g. 1-offset vin)
            cls = "enc" if op in ENC_OPS else "vin"
            counters[cls] += 1
            cid = ("encmut%05d" if cls == "enc" else "vinmut%05d") % counters[cls]
            open(os.path.join(OUTDIR, cid + ".hex"), "w").write(blob.hex())
            cases.append({"id": cid, "parent": rec["tx_hash"],
                          "parent_height": rec["height"], "mutation": op,
                          "label": None, "class": cls,
                          "sha256": hashlib.sha256(blob).hexdigest()})
            made += 1
        print("%-24s %d cases" % (op, made))

    json.dump(cases, open(os.path.join(OUTDIR, "labels.json"), "w"), indent=1)
    total = sum(counters.values())
    print("total cases: %d (enc %d, vin %d) -> %s" %
          (total, counters["enc"], counters["vin"], OUTDIR))


if __name__ == "__main__":
    main()
